import{_ as a,c as o,o as e,ag as r}from"./chunks/framework._xRlcm3f.js";const m=JSON.parse('{"title":"简书配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-jianshu.md","filePath":"platforms/custom-jianshu.md","lastUpdated":1790228279000}'),d={name:"platforms/custom-jianshu.md"};function i(l,t,s,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="简书配置指南" tabindex="-1">简书配置指南 <a class="header-anchor" href="#简书配置指南" aria-label="Permalink to &quot;简书配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到简书。图片默认上传到简书，默认使用 Markdown 发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>在浏览器登录简书。</li><li>无需 API Token，只用 Cookie。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://www.jianshu.com</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认简书 API 地址，一般不改</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/p/[postid]</code></td></tr><tr><td>发布格式</td><td>默认 Markdown</td></tr><tr><td>笔记本</td><td>发布目标笔记本（如「随笔」）</td></tr><tr><td>图床</td><td>默认「当前平台」，图片随文章上传到简书</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 登录简书 → 关闭窗口 → 点「2 自动读取 Cookie」→ 验证。</li><li>快速发布 → 选简书 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>Cookie 验证失败</strong>：确认浏览器已登录简书并能打开创作中心，重新读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」即可，图片随文章上传到简书。</li><li><strong>不能修改所属笔记本</strong>：简书平台限制，已发布文档暂不支持直接编辑笔记本。需要移动时删除原文后重新选择笔记本发布。</li></ul>',10)])])}const _=a(d,[["render",i]]);export{m as __pageData,_ as default};
